<?php $extra=json_decode($item['extra_data']??'',TRUE)?:array();$canApprove=in_array($this->session->userdata('admin_role'),array('admin','ketua'),TRUE); ?>
<div class="admin-title"><div><span class="eyebrow green">Pengajuan Warga</span><h1><?= html_escape($catalog[$item['type']][0]??$item['subject']) ?></h1><p>Pengajuan #<?= (int)$item['id'] ?> · <?= date('d M Y H:i',strtotime($item['created_at'])) ?></p></div><a href="<?= site_url('admin/requests') ?>">← Daftar pengajuan</a></div><div class="ad-request-detail-layout"><section class="panel form-panel"><h2>Data Pemohon</h2><div class="ad-detail-grid"><p><strong>Akun warga</strong><br><?= html_escape($item['display_name']) ?></p><p><strong>Nama pemohon</strong><br><?= html_escape($item['applicant_name']?:$item['display_name']) ?></p><p><strong>NIK</strong><br><?= html_escape($extra['applicant_nik']??'-') ?></p><p><strong>No. HP</strong><br><?= html_escape($extra['applicant_phone']??'-') ?></p><p><strong>Alamat</strong><br><?= html_escape($item['address']?:'-') ?></p><p><strong>Keperluan</strong><br><?= html_escape($item['purpose']?:'-') ?></p></div><h2>Data Warga untuk Surat</h2><div class="ad-detail-grid"><?php foreach(array('applicant_birth_place'=>'Tempat lahir','applicant_birth_date'=>'Tanggal lahir','applicant_gender'=>'Jenis kelamin','applicant_religion'=>'Agama','applicant_occupation'=>'Pekerjaan','applicant_ktp_address'=>'Alamat sesuai KTP') as $key=>$label): ?><p><strong><?= $label ?></strong><br><?= html_escape(($extra[$key]??'')?:'-') ?></p><?php endforeach; ?></div><?php if($type_fields): ?><h2>Data Khusus <?= html_escape($catalog[$item['type']][0]??$item['subject']) ?></h2><div class="ad-detail-grid"><?php foreach($type_fields as $definition): list($field,$label)=$definition; ?><p><strong><?= html_escape($label) ?></strong><br><?= html_escape(($extra[$field]??'')?:'—') ?></p><?php endforeach; ?></div><?php endif; ?><h2>Keterangan Pengajuan</h2><p><?= nl2br(html_escape($item['description'])) ?></p><h2>Dokumen Pendukung</h2><div class="ad-document-list"><?php foreach($documents as $document): ?><a href="<?= site_url('warga/dokumen/'.$document['id']) ?>" target="_blank" rel="noopener">▤ &nbsp; <?= html_escape($document['label']) ?> ↗</a><?php endforeach; ?><?php if($item['attachment']): ?><a href="<?= site_url('warga/lampiran/'.$item['id']) ?>" target="_blank" rel="noopener">▤ &nbsp; Lampiran tambahan ↗</a><?php endif; ?><?php if(!$documents && !$item['attachment']): ?><p>Belum ada dokumen yang dilampirkan.</p><?php endif; ?></div></section><aside class="panel form-panel"><h2>Tinjau Pengajuan</h2><p>Status saat ini: <span class="ad-request-badge <?= html_escape($item['status']) ?>"><?= html_escape(ucfirst($item['status'])) ?></span></p><form method="post"><label>Status<select name="status" id="review-status"><?php foreach(array('diproses'=>'Diproses','ditolak'=>'Ditolak','disetujui'=>'Selesai') as $status=>$label): if(in_array($status,array('disetujui','ditolak','selesai'),TRUE)&&!$canApprove)continue; ?><option value="<?= $status ?>" <?= $item['status']===$status?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Nomor surat <span class="hint">Wajib sebelum persetujuan. Gunakan nomor surat resmi.</span><input name="letter_number" id="letter-number" maxlength="100" value="<?= html_escape($item['letter_number']??'') ?>"></label><label>Catatan pengurus<textarea name="admin_note" rows="5"><?= html_escape($item['admin_note']??'') ?></textarea></label><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><div class="ad-review-actions"><button class="button" type="submit">Simpan Status</button></div></form><?php if($item['status']==='disetujui'&&$item['letter_number']): ?><a class="button" href="<?= site_url('warga/surat/'.$item['id']) ?>" target="_blank" rel="noopener">Lihat / Cetak Surat →</a><?php endif; ?><p class="hint">Kop surat dan identitas penanda tangan dapat diubah di <a href="<?= site_url('admin/letter_settings') ?>">Pengaturan Surat RT</a>.</p></aside></div><script>const statusSelect=document.getElementById('review-status'),numberInput=document.getElementById('letter-number');function updateNumber(){numberInput.required=statusSelect.value==='disetujui'&&<?= $item['type']==='aduan'?'false':'true' ?>}statusSelect.addEventListener('change',updateNumber);updateNumber();</script>
